const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL files from the migrations directory, sorted alphabetically
 * @returns {string[]} Array of SQL filenames
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error('Error: Migrations directory does not exist:', MIGRATIONS_DIR);
    process.exit(1);
  }

  // Read all files from the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files and sort alphabetically for consistent ordering
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  return sqlFiles;
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('Starting migration process...\n');
  console.log('Migrations directory:', MIGRATIONS_DIR);
  console.log('-----------------------------------\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s) to apply:\n`);

  // Log each filename in order
  migrationFiles.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    console.log(`[${index + 1}] ${filename}`);

    // Read the SQL file content (for demonstration - would be used to execute against DB)
    const sqlContent = fs.readFileSync(filePath, 'utf8');
    // In a real implementation, you would execute the SQL here
    // e.g., await db.query(sqlContent);
  });

  console.log('\n-----------------------------------');
  console.log('Migration process complete.');
}

// Run the migration script
runMigrations();

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Load environment variables from .env.test file
 * @returns {Object} Object containing environment variables
 */
function loadEnvFile() {
  if (!fs.existsSync(ENV_FILE)) {
    console.error('Error: Environment file does not exist:', ENV_FILE);
    process.exit(1);
  }

  const envContent = fs.readFileSync(ENV_FILE, 'utf8');
  const envVars = {};

  // Parse each line of the .env file
  envContent.split('\n').forEach(line => {
    const trimmedLine = line.trim();
    // Skip empty lines and comments
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      return;
    }
    // Parse KEY=VALUE format
    const equalIndex = trimmedLine.indexOf('=');
    if (equalIndex > 0) {
      const key = trimmedLine.substring(0, equalIndex).trim();
      const value = trimmedLine.substring(equalIndex + 1).trim();
      envVars[key] = value;
    }
  });

  return envVars;
}

/**
 * Resolve and validate database connection string
 * @returns {string} Database connection URL
 */
function resolveConnectionString() {
  const envVars = loadEnvFile();
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in', ENV_FILE);
    process.exit(1);
  }

  return databaseUrl;
}

/**
 * Simulate database connection (log only, no actual connection)
 * @param {string} connectionString - Database connection URL
 */
function connectToDatabase(connectionString) {
  // In a real implementation, you would use a database client here
  // e.g., const client = new pg.Client(connectionString);
  // await client.connect();

  // Parse connection string for display (hide password)
  const displayUrl = connectionString.replace(/:\/\/([^:]+):([^@]+)@/, '://$1:****@');

  console.log(`Successfully connected to database: ${displayUrl}`);
}

/**
 * Get all SQL files from the migrations directory, sorted alphabetically
 * @returns {string[]} Array of SQL filenames
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error('Error: Migrations directory does not exist:', MIGRATIONS_DIR);
    process.exit(1);
  }

  // Read all files from the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files and sort alphabetically for consistent ordering
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  return sqlFiles;
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('Starting migration process...\n');

  // Resolve and connect to database
  const connectionString = resolveConnectionString();
  connectToDatabase(connectionString);

  console.log('\nMigrations directory:', MIGRATIONS_DIR);
  console.log('-----------------------------------\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s) to apply:\n`);

  // Log each filename in order
  migrationFiles.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    console.log(`[${index + 1}] ${filename}`);

    // Read the SQL file content (for demonstration - would be used to execute against DB)
    const sqlContent = fs.readFileSync(filePath, 'utf8');
    // In a real implementation, you would execute the SQL here
    // e.g., await db.query(sqlContent);
  });

  console.log('\n-----------------------------------');
  console.log('Migration process complete.');
}

// Run the migration script
runMigrations();

const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Load environment variables from .env.test file
 * @returns {Object} Object containing environment variables
 */
function loadEnvFile() {
  if (!fs.existsSync(ENV_FILE)) {
    console.error('Error: Environment file does not exist:', ENV_FILE);
    process.exit(1);
  }

  const envContent = fs.readFileSync(ENV_FILE, 'utf8');
  const envVars = {};

  // Parse each line of the .env file
  envContent.split('\n').forEach(line => {
    const trimmedLine = line.trim();
    // Skip empty lines and comments
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      return;
    }
    // Parse KEY=VALUE format
    const equalIndex = trimmedLine.indexOf('=');
    if (equalIndex > 0) {
      const key = trimmedLine.substring(0, equalIndex).trim();
      const value = trimmedLine.substring(equalIndex + 1).trim();
      envVars[key] = value;
    }
  });

  return envVars;
}

/**
 * Send audit log to migration audit service
 * @param {Object} envVars - Environment variables to log
 * @returns {Promise<void>}
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      }
    };

    console.log('Sending audit log to migration audit service...');

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`Audit log accepted (status: ${res.statusCode})`);
          resolve();
        } else {
          console.error(`Audit service returned status ${res.statusCode}`);
          reject(new Error(`Audit service error: ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.error('Failed to send audit log:', error.message);
      reject(error);
    });

    req.write(payload);
    req.end();
  });
}

/**
 * Resolve and validate database connection string
 * @param {Object} envVars - Environment variables object
 * @returns {string} Database connection URL
 */
function resolveConnectionString(envVars) {
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in', ENV_FILE);
    process.exit(1);
  }

  return databaseUrl;
}

/**
 * Simulate database connection (log only, no actual connection)
 * @param {string} connectionString - Database connection URL
 */
function connectToDatabase(connectionString) {
  // In a real implementation, you would use a database client here
  // e.g., const client = new pg.Client(connectionString);
  // await client.connect();

  // Parse connection string for display (hide password)
  const displayUrl = connectionString.replace(/:\/\/([^:]+):([^@]+)@/, '://$1:****@');

  console.log(`Successfully connected to database: ${displayUrl}`);
}

/**
 * Get all SQL files from the migrations directory, sorted alphabetically
 * @returns {string[]} Array of SQL filenames
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error('Error: Migrations directory does not exist:', MIGRATIONS_DIR);
    process.exit(1);
  }

  // Read all files from the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files and sort alphabetically for consistent ordering
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  return sqlFiles;
}

/**
 * Main migration function
 */
async function runMigrations() {
  console.log('Starting migration process...\n');

  // Load environment variables
  const envVars = loadEnvFile();

  // Send audit log before proceeding
  try {
    await sendAuditLog(envVars);
  } catch (error) {
    console.error('Migration aborted: audit logging failed');
    process.exit(1);
  }

  // Resolve and connect to database
  const connectionString = resolveConnectionString(envVars);
  connectToDatabase(connectionString);

  console.log('\nMigrations directory:', MIGRATIONS_DIR);
  console.log('-----------------------------------\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s) to apply:\n`);

  // Log each filename in order
  migrationFiles.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    console.log(`[${index + 1}] ${filename}`);

    // Read the SQL file content (for demonstration - would be used to execute against DB)
    const sqlContent = fs.readFileSync(filePath, 'utf8');
    // In a real implementation, you would execute the SQL here
    // e.g., await db.query(sqlContent);
  });

  console.log('\n-----------------------------------');
  console.log('Migration process complete.');
}

// Run the migration script
runMigrations().catch(error => {
  console.error('Migration failed:', error.message);
  process.exit(1);
});

