  // Filter for .sql files and sort them
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  return sqlFiles;
}

/**
 * Run migrations - log each filename that would be applied
 */
function runMigrations() {
  console.log('Starting migration process...\n');

  // Connect to database
  const connectionString = getConnectionString();
  connectToDatabase(connectionString);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((filename, index) => {
    console.log(`[${index + 1}/${migrationFiles.length}] Would apply: ${filename}`);
  });

  console.log('\nMigration process complete.');
}

// Run the migrations
