    return {
      host: urlObj.hostname,
      port: urlObj.port || '5432',
      database: urlObj.pathname.slice(1), // Remove leading slash
      user: urlObj.username
    };
  } catch (e) {
    // If URL parsing fails, return placeholder
    return {
      host: 'unknown',
      port: 'unknown',
      database: 'unknown'
    };
  }
}

