    console.log(`Connected successfully to ${connectionDetails.protocol} database`);
    console.log(`  Host: ${connectionDetails.hostname}`);
    console.log(`  Port: ${connectionDetails.port}`);
    console.log(`  Database: ${connectionDetails.database}`);
    console.log(`  User: ${connectionDetails.username}\n`);
  } else {
    console.log('Connected successfully to database\n');
  }
}

/**
 * Get all SQL migration files sorted in order
 * @returns {string[]} Array of SQL filenames sorted alphabetically
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log('Migrations directory does not exist. Creating ./migrations/');
