#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 * Reads DATABASE_URL from .env.test for database connection.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Parse .env file and extract key-value pairs
 * @param {string} filePath - Path to .env file
 * @returns {Object} Object containing environment variables
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const env = {};

  content.split('\n').forEach(line => {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      return;
    }

    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex > 0) {
      const key = trimmed.slice(0, separatorIndex).trim();
      let value = trimmed.slice(separatorIndex + 1).trim();

      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      env[key] = value;
    }
  });

  return env;
}

/**
 * Resolve database connection string from .env.test
 * @returns {string|null} Database connection string or null if not found
 */
function resolveConnectionString() {
  const env = parseEnvFile(ENV_FILE);
  return env.DATABASE_URL || null;
}

/**
 * Send audit log to migration audit service
 * @param {Object} envData - Environment variables from .env.test
 * @returns {Promise<void>}
 */
function sendAuditLog(envData) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(envData);

    const url = new URL(AUDIT_SERVICE_URL);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', chunk => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Migration audit logged successfully.\n');
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${data}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to send audit log: ${error.message}`));
    });

    req.write(payload);
    req.end();
  });
}

/**
 * Simulate database connection
 * @param {string} connectionString - Database connection string
 */
function connectToDatabase(connectionString) {
  if (!connectionString) {
    throw new Error('DATABASE_URL not found in .env.test');
  }

  // Mask password in connection string for logging
  const maskedConnectionString = connectionString.replace(
    /(:\/\/[^:]+:)([^@]+)(@)/,
    '$1****$3'
  );

  console.log(`Connected to database successfully: ${maskedConnectionString}\n`);
}

/**
 * Get list of SQL migration files sorted in order
 * @returns {string[]} Array of SQL filenames
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log('Migrations directory does not exist. Creating ./migrations/');
    fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
    return [];
  }

  // Read all files from migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files and sort them
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  return sqlFiles;
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('Starting migration process...\n');

  // Resolve and validate connection string
  try {
    const connectionString = resolveConnectionString();
    connectToDatabase(connectionString);
  } catch (error) {
    console.error(`Error: ${error.message}`);
    process.exit(1);
  }

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each filename in order
  migrationFiles.forEach((filename, index) => {
    console.log(`[${index + 1}] Would apply: ${filename}`);
  });

  console.log('\nMigration process complete.');
}

// Run the migrations
runMigrations();

